    "codeSnippet": "from fastapi import FastAPI, Depends, HTTPException, status\n\napp = FastAPI()\n\n# Dependinta de securitate\ndef get_current_user(token: str = \"demo-token\"):\n    if token != \"secret-token\":\n        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\"Invalid token\")\n    return {\"username\": \"admin\", \"role\": \"ADMIN\"}\n\n# Endpoint cu injectare de dependinta\n@app.get(\"/admin/dashboard\")\ndef get_dashboard(user: dict = Depends(get_current_user)):\n    return {\"message\": f\"Bine ai venit, {user['username']}!\"}",
